export const searchFormulations = (query) => {
    if (!query) return formulationsData;
    const lowerQuery = query.toLowerCase();
    return formulationsData.filter(f => 
        f.name.toLowerCase().includes(lowerQuery) ||
        f.description.toLowerCase().includes(lowerQuery) ||
        f.tags.some(tag => tag.toLowerCase().includes(lowerQuery))
    );
};

export const getFormulationsByDosha = (doshaType) => {
    const doshaMap = {
        'vata': 'vata',
        'pitta': 'pitta',
        'kapha': 'kapha'
    };
    const dosha = doshaMap[doshaType];
    if (!dosha) return [];
    return formulationsData.filter(f => f.doshaEffect[dosha] < -1).slice(0, 5);
};

export const getFormulationById = (id) => {
    return formulationsData.find(f => f.id === parseInt(id));
};
